using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using System;using System.Linq;
public static class URPVisibleGroundFix {
[MenuItem("Tools/Characters/Fix Visible Ground")]
public static void Fix(){var p=GameObject.Find("Furina Player");int added=0;foreach(var t in Terrain.activeTerrains){var c=t.GetComponent<TerrainCollider>();if(c)c.enabled=true;}foreach(var c in UnityEngine.Object.FindObjectsByType<MeshCollider>())if(c.transform.parent&&c.transform.parent.name=="Terrain_Rivers")UnityEngine.Object.DestroyImmediate(c);foreach(var rr in UnityEngine.Object.FindObjectsByType<MeshRenderer>().OrderByDescending(r=>r.bounds.size.x*r.bounds.size.z).Take(16))Debug.Log("BIG_MESH "+rr.name+" parent="+rr.transform.parent?.name+" "+rr.bounds);foreach(var mf in UnityEngine.Object.FindObjectsByType<MeshFilter>()){var r=mf.GetComponent<Renderer>();if(!r||!mf.sharedMesh||mf.transform.IsChildOf(p.transform))continue;string n=mf.name.ToLowerInvariant();if(n.Contains("water")||n.Contains("fog")||n.Contains("sky"))continue;if(!n.StartsWith("river")&&!n.StartsWith("lake")&&(n.Contains("terrain")||n.Contains("ground")||mf.transform.parent&&mf.transform.parent.name.ToLowerInvariant().Contains("terrain"))&&Mathf.Max(r.bounds.size.x,r.bounds.size.z)>20){var c=mf.GetComponent<MeshCollider>();if(!c){c=mf.gameObject.AddComponent<MeshCollider>();c.sharedMesh=mf.sharedMesh;added++;}Debug.Log("VISIBLE_GROUND "+mf.name+" "+r.bounds);}}
Physics.SyncTransforms();Vector3 origin=p.transform.position;bool placed=false;for(int ring=0;ring<35&&!placed;ring++)for(int a=0;a<16&&!placed;a++){var sample=origin+new Vector3(Mathf.Cos(a*Mathf.PI/8)*ring*5,0,Mathf.Sin(a*Mathf.PI/8)*ring*5);var hits=Physics.RaycastAll(new Vector3(sample.x,1000,sample.z),Vector3.down,2000,~0,QueryTriggerInteraction.Ignore).OrderBy(h=>h.distance);foreach(var h in hits){if(!(h.collider is MeshCollider)&&!(h.collider is TerrainCollider)||h.normal.y<.8f||h.collider.transform.IsChildOf(p.transform))continue;string n=h.collider.name.ToLowerInvariant();if(!(h.collider is TerrainCollider))continue;if(Physics.OverlapCapsule(h.point+Vector3.up*.45f,h.point+Vector3.up*1.5f,.3f,~0,QueryTriggerInteraction.Ignore).Any(c=>!c.transform.IsChildOf(p.transform)))continue;var follow=Camera.main.GetComponent<Game.ThirdPerson.ThirdPersonFollowCamera>();var eye=h.point+Vector3.up*1.55f;var view=eye+Quaternion.Euler(15,follow.yaw,0)*Vector3.back*4;RaycastHit obstruction;if(Physics.Linecast(eye,view,out obstruction,~0,QueryTriggerInteraction.Ignore)&&!obstruction.collider.transform.IsChildOf(p.transform))continue;var cc=p.GetComponent<CharacterController>();cc.enabled=false;p.transform.position=h.point+Vector3.up*.06f;cc.enabled=true;placed=true;break;}}
if(!placed)throw new Exception("No visible ground spawn");var cam=Camera.main;cam.GetComponent<Game.ThirdPerson.ThirdPersonFollowCamera>().UpdateView(1);PrefabUtility.SaveAsPrefabAsset(p,"Assets/Game/Prefabs/FurinaPlayer.prefab");EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());AssetDatabase.SaveAssets();Debug.Log("VISIBLE_GROUND_FIXED added="+added+" spawn="+p.transform.position);}
}




